urlset:
{{ $now := now }}
{{/* 🎯 On retient les pages possédant une référence d'AVP et dont la date de clôture
     n'est pas dépassée.
     Depuis le 09/09/2026 les AVP clos ne sont PLUS supprimés du dépôt mais archivés
     (content/archives/, `archive: true`) : sans ce filtre ils seraient soumis à Google
     comme des offres ouvertes. Le contrôle de date ci-dessous les écarterait déjà, mais
     on ne fait pas reposer une soumission externe sur ce seul garde-fou. */}}
{{ range partial "avp-actives.html" .Site.RegularPages }}
  {{ if .Params.ref }}
    {{ $ouvert := true }}
    {{ with .Params.date_cloture }}
      {{ if lt (time.AsTime .) $now }}{{ $ouvert = false }}{{ end }}
    {{ end }}
    {{ if $ouvert }}

    {{ .Permalink }}
    {{ .Lastmod.Format "2006-01-02T15:04:05-07:00" }}
    daily
    0.8

    {{ end }}
  {{ end }}
{{ end }}
